import 'package:flutter/material.dart';
import 'package:video_player/video_player.dart';
import '../models/iptv_item.dart';
class IptvPlayerScreen extends StatefulWidget{const IptvPlayerScreen({super.key,required this.item});final IptvItem item;@override State<IptvPlayerScreen> createState()=>_State();}
class _State extends State<IptvPlayerScreen>{VideoPlayerController? c;String? error;@override void initState(){super.initState();_start();}Future<void>_start()async{try{final x=VideoPlayerController.networkUrl(Uri.parse(widget.item.url),httpHeaders:widget.item.headers);c=x;await x.initialize();await x.play();if(mounted)setState((){});}catch(e){if(mounted)setState(()=>error=e.toString());}}@override Widget build(BuildContext context){final x=c;return Scaffold(backgroundColor:Colors.black,appBar:AppBar(title:Text(widget.item.name),backgroundColor:Colors.black),body:Center(child:error!=null?Text(error!,style:const TextStyle(color:Colors.white)):x==null||!x.value.isInitialized?const CircularProgressIndicator():GestureDetector(onTap:(){setState(()=>x.value.isPlaying?x.pause():x.play());},child:AspectRatio(aspectRatio:x.value.aspectRatio==0?16/9:x.value.aspectRatio,child:VideoPlayer(x)))));} @override void dispose(){c?.dispose();super.dispose();}}
